<template>
  <section class="process-panel" aria-label="生产原理演示控制">
    <div class="process-title"><div><span class="eyebrow">{{ session.equipmentId }} · 生产主线</span><h3>{{ current.label }}</h3></div><span class="demo-badge">原理演示 / 非现场状态 / 非操作规程</span></div>
    <div class="steps" aria-label="跳转示教步骤"><button v-for="(step,i) in steps" :key="step.label" :aria-current="i === index ? 'step' : undefined" @click="$emit('seek', i * 12)"><span>{{ String(i+1).padStart(2,'0') }}</span>{{ step.label }}</button></div>
    <p class="step-note">{{ current.note }}<span v-if="index===2">当前：{{ wash.label }}</span></p>
    <div class="playback"><button class="play" :aria-label="session.paused ? '播放生产演示' : '暂停生产演示'" @click="$emit('toggle')">{{ session.paused ? '▶ 播放' : 'Ⅱ 暂停' }}</button><button class="replay" aria-label="重播生产演示" @click="$emit('replay')">↻ 重播</button><label class="timeline">演示进度<input type="range" min="0" max="60" step="0.1" :value="session.time" @input="$emit('seek', Number(($event.target as HTMLInputElement).value))" /></label><output>{{ session.time.toFixed(1) }} / 60s</output><label class="speed">速度<select :value="session.speed" @change="$emit('speed', Number(($event.target as HTMLSelectElement).value))"><option :value="0.5">0.5×</option><option :value="1">1×</option><option :value="2">2×</option></select></label></div>
    <div class="process-footer"><label><input type="checkbox" :checked="session.followCamera" @change="$emit('follow', ($event.target as HTMLInputElement).checked)" /> 跟随示教镜头</label><span>手动操作立即接管镜头；时长仅为讲解节奏。</span><button @click="$emit('exit')">退出示教</button></div>
  </section>
</template>
<script setup lang="ts">
import { computed } from 'vue'
import type { DemoSession } from '@/types/twin'
import { washState } from './process/process-hardware'
const props=defineProps<{session:DemoSession}>()
defineEmits<{seek:[time:number];toggle:[];replay:[];speed:[value:number];follow:[value:boolean];exit:[]}>()
const steps=[{label:'进料',note:'观察进料路径与罐内物料的示意变化；接口与流路仍须工程核验。'},{label:'过滤',note:'液相通过简化过滤面，固相逐步截留；视觉量没有实测单位。'},{label:'洗涤',note:'按六个讲解步骤观察进入、升降、混合和排液。'},{label:'干燥',note:'观察供热、搅拌与气体移出的原理表达；没有真实温压或合格判定。'},{label:'出料',note:'观察堵头回缩与搅拌辅助出料的示意；内部形状和行程仍待核。'}]
const index=computed(()=>Math.min(4,Math.floor(props.session.time/12)))
const current=computed(()=>steps[index.value]!)
const wash=computed(()=>washState(Math.max(0,Math.min(1,(props.session.time-24)/12))))
</script>
<style scoped>
