0px){.process-panel{padding:15px}.process-title{align-items:flex-start;flex-direction:column}.steps{gap:4px}.steps button{padding:10px 4px;gap:4px;font-size:12px}.steps span{display:none}.playback{flex-wrap:wrap}.timeline{order:5;flex-basis:100%}.process-footer{flex-wrap:wrap}.process-footer>span{width:100%;order:3}}
